// common/workflows-contract/bindings.ts
//
// `bindings.json` schema — authored at workflow install time by the
// installing agent (or auto-generated by the bundled install script).
// Lives next to `manifest.json` inside the workflow install dir.
//
// Per the FEAT-SLOTS spec: one model, three resolution strategies
// expressed as four binding kinds. The installing agent decides which to
// use for each `agentRequirement` declared by the workflow.
//
// V1 layout — bindings live with the install record:
//   ~/.marshal/marshal-workflows/<id>/bindings.json
//
// `targetRepoPath` (top-level) records the repo the bindings were
// authored against (null for standalone installs). The engine passes
// that path through to `repo-agent` / `create-agent` bindings at spawn
// time so the existing `selectRepositoryAgent` machinery in
// `electron/sessions.ts` can find the .agent.md file under
// `<targetRepoPath>/.github/agents/`.

import { z } from "zod";

/** Use an existing `<repo>/.github/agents/<agentName>.agent.md`. */
export const RepoAgentBindingSchema = z
  .object({
    kind: z.literal("repo-agent"),
    /** Agent name as it appears in `.github/agents/` (without the `.agent.md`). */
    agentName: z.string().min(1),
    /** Optional Co-create workspace name; falls back to file's `targetRepoPath`. */
    workspaceName: z.string().optional(),
    /** When true, validate the agent exists in the bound repo before spawning. */
    requireRepoLocal: z.boolean().optional(),
  })
  .strict();
export type RepoAgentBinding = z.infer<typeof RepoAgentBindingSchema>;

/**
 * Use the agent.md the workflow itself shipped under
 * `<workflowDir>/<agentRequirement.defaultAgent.agentMdPath>`. The
 * binding carries no other fields — the path is read from the
 * workflow's `agentRequirements` at resolve time.
 */
export const ShippedAgentBindingSchema = z
  .object({
    kind: z.literal("shipped-agent"),
  })
  .strict();
export type ShippedAgentBinding = z.infer<typeof ShippedAgentBindingSchema>;

/**
 * The installing agent authored a brand-new `.agent.md` file inside the
 * target repo's `.github/agents/` directory at install time. The binding
 * records the agent name and (optionally) when it was created.
 */
export const CreateAgentBindingSchema = z
  .object({
    kind: z.literal("create-agent"),
    /** Repo-relative path written at install time, e.g. `.github/agents/wsr-investigator.agent.md`. */
    agentMdPath: z.string().min(1),
    /** Agent name extracted from `agentMdPath` for runtime lookup. */
    agentName: z.string().min(1),
    /** Co-create workspace name the file was authored into. */
    workspaceName: z.string().optional(),
    /** Epoch ms when the file was written. */
    createdAt: z.number().int().nonnegative().optional(),
  })
  .strict();
export type CreateAgentBinding = z.infer<typeof CreateAgentBindingSchema>;

/**
 * Don't use a custom agent at all. The engine prepends the slot's
 * `defaultPersonality` + `role` (from `agentRequirements`) to the user's
 * prompt and spawns a vanilla general-purpose subagent.
 */
export const DefaultWithRoleBindingSchema = z
  .object({
    kind: z.literal("default-with-role"),
  })
  .strict();
export type DefaultWithRoleBinding = z.infer<typeof DefaultWithRoleBindingSchema>;

export const BindingSchema = z.discriminatedUnion("kind", [
  RepoAgentBindingSchema,
  ShippedAgentBindingSchema,
  CreateAgentBindingSchema,
  DefaultWithRoleBindingSchema,
]);
export type Binding = z.infer<typeof BindingSchema>;

export const BindingsFileSchema = z
  .object({
    version: z.literal(1),
    /** slot id → binding. Must cover every slot in the workflow's
     *  `agentRequirements`. */
    bindings: z.record(z.string().min(1), BindingSchema),
    /**
     * Absolute path of the repo the install targets. Null for
     * standalone installs. `repo-agent` and `create-agent` bindings
     * look here first when resolving `.github/agents/`.
     */
    targetRepoPath: z.string().nullable(),
    /**
     * Absolute path to an authoritative `.github` folder whose agents and
     * skills can satisfy repo-agent bindings and workflow spawn defaults.
     */
    externalContextPath: z.string().nullable().optional(),
    /**
     * Optional phase/step label → skill allow-list. A value of ["*"] means all
     * repo-local skills for the workflow repo. Concrete names are passed to
     * the subagent session's existing per-session skill allow-list.
     */
    skillPhaseBindings: z.record(z.string().min(1), z.array(z.string().min(1))).optional(),
  })
  .strict();
export type BindingsFile = z.infer<typeof BindingsFileSchema>;

/**
 * Empty bindings file (no slots required) — convenience for workflows
 * that never call `ctx.run({ slot })` and only use `agentName`.
 */
export const EMPTY_BINDINGS: BindingsFile = Object.freeze({
  version: 1,
  bindings: {},
  targetRepoPath: null,
  externalContextPath: null,
});

/** Discriminated kind literal — re-exported for convenience in switches. */
export type BindingKind = Binding["kind"];

/** All recognised binding kinds, useful for exhaustiveness assertions. */
export const ALL_BINDING_KINDS: ReadonlyArray<BindingKind> = [
  "repo-agent",
  "shipped-agent",
  "create-agent",
  "default-with-role",
];
